// Stato condiviso dell'app: tutto ciò che l'app sa del Player e dei comandi in corso.

import { FIXED_FX, PLAYER_MAX_BANKS } from "../kemper-midi.js";
import { MAX_BANKS_KEY } from "./config.js";

function readMaxBanks() {
  try {
    const value = Number(localStorage.getItem(MAX_BANKS_KEY));
    if (Number.isInteger(value) && value >= 5 && value <= PLAYER_MAX_BANKS) return value;
  } catch { /* facoltativo */ }
  return PLAYER_MAX_BANKS;
}

